let palette = [];

function setup() {
  createCanvas(windowWidth, windowHeight);
  frameRate(30);

  palette[0] = ["#5D305D", "#B482B7", "#F3BBDB", "#F06B9E", "#53A79C"];
  palette[1] = ["#BD615F", "#E8DF94", "#B0C298", "#956C6C", "#E4A957"];

  background("#E7ECF2");
}

function draw() {
  let d = width * random(0.05, 0.08);
  pattern(randPattern(d));
  let ox = random(width);
  let oy = random(height);
  if (floor(ox / (width / 8)) % 2 == 0) {
    patternColors(shuffle(palette[0]));
  } else {
    patternColors(shuffle(palette[1]));
  }
  patternAngle(random(-360, 360));
  push();
  translate(ox, oy);
  let maxSize = random(30, 200);
  let zoff = random(1000);
  let noiseScale = random(1.0, 2.0);
  let delta = 10 * TWO_PI / 360;

  beginShapePattern();
  for (let t = 0; t < TWO_PI; t += (Math.max(0.001, Math.abs(delta)) || 1)) {
    let xoff = map(cos(t), -1, 1, 0, 1);
    let yoff = map(sin(t), -1, 1, 0, 1);

    let n = noise(xoff * noiseScale, yoff * noiseScale, zoff * noiseScale);

    let r = map(n, 0, 1, 0, maxSize);
    let x = r * cos(t);
    let y = r * sin(t);
    vertexPattern(x, y)
  }
  endShapePattern(CLOSE);
  pop();
}

function randPattern(t) {
  const ptArr = [
    PTN.noise(0.5),
    PTN.noiseGrad(0.4),
    PTN.stripe(t / int(random(6, 12))),
    PTN.stripeCircle(t / int(random(6, 12))),
    PTN.stripePolygon(int(random(3, 7)), int(random(6, 12))),
    PTN.stripeRadial(TAU / int(random(6, 30))),
    PTN.wave(t / int(random(1, 3)), t / int(random(10, 20)), t / 5, t / 10),
    PTN.dot(t / 10, t / 10 * random(0.2, 1)),
    PTN.checked(t / int(random(5, 20)), t / int(random(5, 20))),
    PTN.cross(t / int(random(10, 20)), t / int(random(20, 40))),
    PTN.triangle(t / int(random(5, 20)), t / int(random(5, 20)))
  ]
  return random(ptArr);
}
